CREATE TABLE catalog_jobs(id text PRIMARY KEY,tenant_id text NOT NULL,object_id text NOT NULL,brand_id text,revision integer NOT NULL,actor_id text NOT NULL,input jsonb NOT NULL,status text NOT NULL DEFAULT 'queued',result jsonb,error_code text,lease_owner text,lease_expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,object_id) REFERENCES catalog_items(tenant_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES users(tenant_id,id),UNIQUE(tenant_id,object_id,revision));
